/bin/bash -lc "python -c 'import urllib.request; from html.parser import HTMLParser
class P(HTMLParser):
 def __init__(self): super().__init__(); self.in_title=False; self.title=\"\"
 def handle_starttag(self,t,a): self.in_title = t.lower()==\"title\"
 def handle_endtag(self,t):
  if t.lower()==\"title\": self.in_title=False
 def handle_data(self,d):
  if self.in_title: self.title += d
with urllib.request.urlopen(\"https://example.com\") as x: p=P(); p.feed(x.read().decode()); print(p.title)'"

